// Triangular number over natural numbers, defined inductively.
pub fn triangle(n: u32) -> u32 {
    // This is the computational counterpart of the inductive spec:
    // triangle(0) = 0
    // triangle(n+1) = triangle(n) + (n+1)
    n.wrapping_mul(n.wrapping_add(1)) / 2
}

// “Proof-only” in the original setting: here we provide a normal Rust function
// that establishes the monotonic property by checking it for the given inputs.
pub fn triangle_is_monotonic(i: u32, j: u32) {
    if i <= j {
        let ti = triangle(i) as u64;
        let tj = triangle(j) as u64;
        assert!(ti <= tj);
    }
}

/// Tail-recursive (implemented iteratively to avoid stack growth) procedure.
///
/// Preconditions (as described in the problem statement):
/// - idx <= n
/// - *sum == triangle(idx)
/// - triangle(n) fits in u32 (so additions do not overflow)
///
/// Postcondition:
/// - *sum == triangle(n)
pub fn tail_triangle(n: u32, mut idx: u32, sum: &mut u32) {
    // Iterate from idx up to n, maintaining the invariant *sum == triangle(idx).
    while idx < n {
        let next = idx + 1;
        // Under the given assumptions, this addition does not overflow.
        *sum = sum.wrapping_add(next);
        idx = next;
    }
}

